'use client'

import * as React from 'react'
import { cn, popoverConnect, popoverContentVariants, popoverMachine } from "@/lib/utils"
import { mergeProps, normalizeProps, useMachine } from '@zag-js/react'
import { createPortal } from 'react-dom'

import { Slot } from './slot'

type Placement =
  | 'top'
  | 'top-start'
  | 'top-end'
  | 'bottom'
  | 'bottom-start'
  | 'bottom-end'
  | 'left'
  | 'left-start'
  | 'left-end'
  | 'right'
  | 'right-start'
  | 'right-end'

const PopoverContext = React.createContext<{
  api: ReturnType<typeof popoverConnect>
} | null>(null)

function usePopover() {
  const context = React.useContext(PopoverContext)
  if (!context) {
    throw new Error('Popover components must be used within Popover')
  }
  return context
}

const Popover = ({
  children,
  open,
  defaultOpen,
  onOpenChange,
  modal = false,
  ids,
}: {
  children: React.ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  modal?: boolean
  ids?: {
    anchor?: string
    trigger?: string
    content?: string
    title?: string
    description?: string
    closeTrigger?: string
    positioner?: string
    arrow?: string
  }
}) => {
  const service = useMachine(popoverMachine, {
    id: React.useId(),
    open,
    defaultOpen,
    modal,
    ids,
    onOpenChange: (details) => onOpenChange?.(details.open),
  })

  const api = React.useMemo(() => popoverConnect(service, normalizeProps), [service])

  return <PopoverContext.Provider value={{ api }}>{children}</PopoverContext.Provider>
}
Popover.displayName = 'Popover'

const PopoverTrigger = React.forwardRef<
  HTMLButtonElement,
  React.ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }
>(({ className, onClick, asChild = false, children, ...props }, ref) => {
  const { api } = usePopover()

  const Comp = asChild ? Slot : 'button'
  const triggerProps = api.getTriggerProps()
  const mergedProps = mergeProps(triggerProps, props)

  if (asChild) {
    return (
      <Comp ref={ref} data-slot="popover-trigger" className={cn(className)} {...mergedProps}>
        {children}
      </Comp>
    )
  }

  return (
    <Comp
      ref={ref}
      type="button"
      data-slot="popover-trigger"
      className={cn(className)}
      {...mergedProps}
    >
      {children}
    </Comp>
  )
})
PopoverTrigger.displayName = 'PopoverTrigger'

const PopoverContent = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & {
    align?: 'center' | 'start' | 'end'
    side?: 'top' | 'bottom' | 'left' | 'right'
    sideOffset?: number
    showArrow?: boolean
  }
>(
  (
    {
      className,
      align = 'center',
      side = 'bottom',
      sideOffset = 4,
      showArrow = false,
      style,
      children,
      ...props
    },
    ref
  ) => {
    const { api } = usePopover()
    const isOpen = api.open

    const placement = (align === 'center' ? side : `${side}-${align}`) as Placement
    React.useLayoutEffect(() => {
      if (!api.open || typeof window === 'undefined') return
      api.reposition({ placement, gutter: sideOffset })
    }, [api, placement, sideOffset])

    if (!isOpen) return null
    if (typeof window === 'undefined') return null

    const positionerProps = api.getPositionerProps()
    const contentProps = api.getContentProps()
    const mergedProps = mergeProps(contentProps, props)

    return createPortal(
      <div {...positionerProps} style={{ ...positionerProps.style, zIndex: 50 }}>
        <div
          ref={ref}
          data-slot="popover-content"
          data-state="open"
          data-align={align}
          style={{ ...mergedProps.style, ...style }}
          className={cn(popoverContentVariants(), showArrow ? 'relative' : undefined, className)}
          {...mergedProps}
        >
          {children}
          {showArrow ? (
            <span
              data-slot="popover-arrow"
              className="absolute -top-1 left-6 h-2 w-2 rotate-45 border border-border bg-popover"
            />
          ) : null}
        </div>
      </div>,
      document.body
    )
  }
)
PopoverContent.displayName = 'PopoverContent'

export { Popover, PopoverTrigger, PopoverContent, PopoverAnchor }

const PopoverAnchor = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  (props, ref) => <div ref={ref} {...props} />
)
PopoverAnchor.displayName = 'PopoverAnchor'

import { computed, watch } from 'vue'
import { normalizeProps, useMachine } from '@zag-js/vue'
import { popoverConnect, popoverMachine } from "@/lib/utils"
import type { PositioningOptions } from '@zag-js/popper'

export interface UsePopoverProps {
    id?: string
    open?: boolean
    defaultOpen?: boolean
    modal?: boolean
    closeOnInteractOutside?: boolean
    closeOnEscape?: boolean
    positioning?: PositioningOptions
}

export interface UsePopoverEmits {
    (e: 'update:open', value: boolean): void
    (e: 'change', value: boolean): void
}

let staticId = 0

export function usePopover(props: UsePopoverProps, emit: UsePopoverEmits) {
    const localId = `popover-${++staticId}`

    const machineProps = computed(() => ({
        id: props.id ?? localId,
        open: props.open,
        defaultOpen: props.open === undefined ? props.defaultOpen : undefined,
        modal: props.modal,
        closeOnInteractOutside: props.closeOnInteractOutside,
        closeOnEscape: props.closeOnEscape,
        positioning: props.positioning,
        onOpenChange(details: { open: boolean }) {
            emit('update:open', details.open)
            emit('change', details.open)
        },
    }))

    const service = useMachine(popoverMachine, machineProps)
    const api = computed(() => popoverConnect(service, normalizeProps))

    watch(
        () => props.open,
        (val?: boolean) => {
            if (val !== undefined && val !== api.value.open) {
                api.value.setOpen(val)
            }
        }
    )

    return api
}

import { setupPopoverMachine } from './use-popover'

type WeappPopoverApi = {
  triggerProps?: { onClick?: () => void }
  open?: () => void
  close?: () => void
}

type WeappService = {
  setContext: (context: Record<string, object>) => void
}
type MachineEvent = string | { type: string; [key: string]: object }
type MachineSend = (event: MachineEvent) => void

type WeappPopoverInternal = WechatMiniprogram.Component.InstanceMethods<WeappPopoverApi> & {
  _service?: WeappService
  _cleanup?: () => void
  _send?: (event: object) => void
  _connect?: (state: object, send: MachineSend) => WeappPopoverApi
  data: {
    api: WeappPopoverApi
  }
  properties: {
    open: boolean
    modal: boolean
    portalled: boolean
    closeOnInteractOutside: boolean
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    open: { type: Boolean, value: false },
    modal: { type: Boolean, value: false },
    portalled: { type: Boolean, value: true },
    closeOnInteractOutside: { type: Boolean, value: true },
    id: { type: String, value: 'popover' },
    extClass: { type: String, value: '' },
  },

  data: {
    api: {} as WeappPopoverApi,
    className: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappPopoverInternal
      const { controller, connect } = setupPopoverMachine(self)

      self._service = controller.service as WeappService
      self._cleanup = controller.start()
      self._send = controller.send as MachineSend
      self._connect = connect
    },
    detached() {
      const self = this as WeappPopoverInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappPopoverInternal
      if (!state || !self._send || !self._connect) return
      const api = self._connect(state, self._send) as WeappPopoverApi
      this.setData({ api, className: this.properties.extClass })
    },

    'open': function (val) {
      const self = this as WeappPopoverInternal
      if (self._service) {
        if (val) {
          self.data.api.open?.()
        } else {
          self.data.api.close?.()
        }
      }
    },
  },

  methods: {
    onTriggerTap() {
      const self = this as WeappPopoverInternal
      self.data.api.triggerProps?.onClick?.()
    },
    onBackdropTap() {
      const self = this as WeappPopoverInternal
      self.data.api.close?.()
    },
    onCloseTap() {
      const self = this as WeappPopoverInternal
      self.data.api.close?.()
    },
  },
})

import { popoverContentVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  relations: {
    '../popover/popover': {
      type: 'parent',
    },
  },
  externalClasses: ['ext-class'],
  properties: {
    extClass: { type: String, value: '' },
  },
  data: {
    visible: false,
    style: 'opacity: 0;', // Initial hidden
    className: '',
  },
  observers: {
    extClass: function (extClass: string) {
      this.setData({
        // Simulating data-state for variants if needed?
        // Shared variant uses `data-[state=open]:animate-in`.
        // WeApp won't trigger that animation naturally without state change.
        // For now, allow base classes.
        className: popoverContentVariants({ className: extClass })
      })
    }
  },
  methods: {
    showForMeasure() {
      this.setData({
        visible: true,
        style: 'opacity: 0; pointer-events: none;',
      })
    },
    updatePosition(top: number, left: number) {
      this.setData({
        style: `top: ${top}px; left: ${left}px; opacity: 1; transition: opacity 0.2s;`,
      })
    },
    hide() {
      this.setData({ visible: false, style: 'opacity: 0;' })
    },
    getRect() {
      return new Promise((resolve) => {
        this.createSelectorQuery()
          .select('#popover-content')
          .boundingClientRect((rect) => {
            resolve(rect)
          })
          .exec()
      })
    },
    noop() { },
  },
})

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  relations: {
    '../popover/popover': {
      type: 'parent',
    },
  },
  methods: {
    onTap() {
      const parents = this.getRelationNodes('../popover/popover')
      if (parents.length) {
        parents[0].toggle()
      }
    },
    getRect() {
      return new Promise((resolve) => {
        this.createSelectorQuery()
          .select('#popover-trigger')
          .boundingClientRect((rect) => {
            resolve(rect)
          })
          .exec()
      })
    },
  },
})
